package com.tonyscratch.tsdj.audio

import java.util.Random
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.exp
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.math.sin
import kotlin.math.tanh

/**
 * The built-in sound banks. Every sound is generated by code (no recordings), so there are
 * no copyright issues and nothing to download. Generated once, in the background, at start-up.
 */
object SoundSynth {

    fun builtInBanks(sr: Int): List<SampleBank> = listOf(
        SampleBank("DJ FX", false, arrayOf(airHorn(sr), siren(sr), dubSiren(sr), laser(sr), rewind(sr), gunshot(sr), bombDrop(sr), scratch(sr))),
        SampleBank("BUILD-UPS", false, arrayOf(riser(sr), downlifter(sr), noiseUp(sr), noiseDown(sr), impact(sr), subDrop(sr), reverseCymbal(sr), vinylStop(sr))),
        SampleBank("DRUMS", false, arrayOf(kick(sr), snare(sr), clap(sr), hat(sr, false), hat(sr, true), rim(sr), tom(sr), bass808(sr))),
        SampleBank("HYPE", false, arrayOf(whistle(sr), cowbell(sr), zap(sr), drumRoll(sr), bell(sr), alarm(sr), woosh(sr), glitch(sr))),
    )

    // =========================================================================================
    // Helpers
    // =========================================================================================

    /** Band-limited oscillator (polyBLEP) so saws and squares don't sound harsh. */
    private class Osc {
        var ph = 0.0
        private fun blep(t: Double, dt: Double): Double = when {
            t < dt -> { val x = t / dt; x + x - x * x - 1.0 }
            t > 1.0 - dt -> { val x = (t - 1.0) / dt; x * x + x + x + 1.0 }
            else -> 0.0
        }
        private fun step(f: Double, sr: Int): Double {
            val dt = f / sr
            ph += dt
            if (ph >= 1.0) ph -= floor(ph)
            return dt
        }
        fun sine(f: Double, sr: Int): Double { step(f, sr); return sin(2 * PI * ph) }
        fun saw(f: Double, sr: Int): Double { val dt = step(f, sr); return 2 * ph - 1 - blep(ph, dt) }
        fun square(f: Double, sr: Int): Double {
            val dt = step(f, sr)
            var v = if (ph < 0.5) 1.0 else -1.0
            v += blep(ph, dt)
            v -= blep((ph + 0.5) % 1.0, dt)
            return v
        }
        fun tri(f: Double, sr: Int): Double { step(f, sr); return 1.0 - 4.0 * abs(ph - 0.5) }
    }

    private class OnePole(private val a: Double) {
        var y = 0.0
        fun lp(x: Double): Double { y += a * (x - y); return y }
        fun hp(x: Double): Double { y += a * (x - y); return x - y }
    }

    private fun coef(fc: Double, sr: Int) = 1.0 - exp(-2.0 * PI * fc / sr)

    private class Noise(seed: Long) {
        private val rnd = Random(seed)
        fun next(): Double = rnd.nextDouble() * 2 - 1
    }

    private fun len(sr: Int, sec: Double) = (sr * sec).toInt()

    /** Normalise to a safe peak, add tiny fades and trim silence at the end. */
    private fun finish(name: String, l: FloatArray, r: FloatArray, sr: Int, peak: Float = 0.9f): SampleSound {
        var end = l.size
        while (end > 1 && abs(l[end - 1]) < 1e-4f && abs(r[end - 1]) < 1e-4f) end--
        val ll = l.copyOf(end)
        val rr = r.copyOf(end)
        var p = 1e-6f
        for (i in 0 until end) p = max(p, max(abs(ll[i]), abs(rr[i])))
        val g = peak / p
        val fadeIn = min(end, (sr * 0.002).toInt())
        val fadeOut = min(end, (sr * 0.01).toInt())
        for (i in 0 until end) {
            var e = 1f
            if (i < fadeIn) e = i / fadeIn.toFloat()
            if (i >= end - fadeOut) e = min(e, (end - 1 - i) / fadeOut.toFloat())
            ll[i] *= g * e
            rr[i] *= g * e
        }
        return SampleSound(name, ll, rr)
    }

    private fun mono(name: String, x: DoubleArray, sr: Int, peak: Float = 0.9f): SampleSound {
        val l = FloatArray(x.size) { x[it].toFloat() }
        return finish(name, l, l.copyOf(), sr, peak)
    }

    /** Add a reverb tail (Freeverb) to a mono sound. */
    private fun withReverb(name: String, x: DoubleArray, sr: Int, wet: Double, room: Float, extraSec: Double): SampleSound {
        val n = x.size + len(sr, extraSec)
        val l = FloatArray(n)
        val r = FloatArray(n)
        val verb = Freeverb(sr)
        for (i in 0 until n) {
            val dry = if (i < x.size) x[i] else 0.0
            verb.process((dry * 0.015).toFloat(), room, 0.3f)
            l[i] = (dry + verb.outL * 3 * wet).toFloat()
            r[i] = (dry + verb.outR * 3 * wet).toFloat()
        }
        return finish(name, l, r, sr)
    }

    private fun env(t: Double, attack: Double, decay: Double): Double =
        if (t < 0) 0.0 else min(1.0, t / attack) * exp(-t / decay)

    /** Gate envelope for a list of (start, end) on-segments, with soft edges. */
    private fun gate(t: Double, segs: List<Pair<Double, Double>>, att: Double = 0.006, rel: Double = 0.025): Double {
        var v = 0.0
        for ((s, e) in segs) {
            if (t < s || t > e + rel) continue
            val a = min(1.0, (t - s) / att)
            val r = if (t > e) max(0.0, 1.0 - (t - e) / rel) else 1.0
            v = max(v, a * r)
        }
        return v
    }

    /** A short musical loop (kick, hats, chord) used as source material for some effects. */
    private fun beatLoop(sr: Int, sec: Double, seed: Long): DoubleArray {
        val n = len(sr, sec)
        val out = DoubleArray(n)
        val beat = 60.0 / 124.0
        val oscs = Array(3) { Osc() }
        val noise = Noise(seed)
        val hp = OnePole(coef(7000.0, sr))
        val chord = doubleArrayOf(220.0, 261.63, 329.63)
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val tb = t % beat
            val kick = sin(2 * PI * (50 * tb + 110 * 0.03 * (1 - exp(-tb / 0.03)))) * exp(-tb / 0.2)
            val off = (t + beat / 2) % beat
            val hat = hp.hp(noise.next()) * exp(-off / 0.03) * 0.5
            var c = 0.0
            for (k in 0..2) c += oscs[k].saw(chord[k], sr)
            val stab = c * 0.12 * exp(-((t % (beat * 2))) / 0.35)
            out[i] = kick * 0.8 + hat + stab
        }
        return out
    }

    /** Read [src] with a varying playback position (seconds) — used for scratch, rewind and brake sounds. */
    private fun readAt(src: DoubleArray, sr: Int, posSec: Double): Double {
        val p = posSec * sr
        val i = floor(p).toInt()
        if (i < 0 || i + 1 >= src.size) return 0.0
        val f = p - i
        return src[i] * (1 - f) + src[i + 1] * f
    }

    // =========================================================================================
    // DJ FX bank
    // =========================================================================================

    fun airHorn(sr: Int): SampleSound {
        val n = len(sr, 1.4)
        val x = DoubleArray(n)
        val segs = listOf(0.0 to 0.30, 0.37 to 0.46, 0.52 to 0.61, 0.67 to 1.2)
        val oscs = Array(4) { Osc() }
        val ratios = doubleArrayOf(1.0, 1.004, 0.996, 2.003)
        val amps = doubleArrayOf(1.0, 0.8, 0.8, 0.35)
        val hp = OnePole(coef(260.0, sr))
        val bp = Biquad().apply { setBandPass(sr, 1400.0, 0.8) }
        val lp = OnePole(coef(5200.0, sr))
        val f0 = 480.0
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val g = gate(t, segs)
            val segStart = segs.lastOrNull { t >= it.first }?.first ?: 0.0
            val bend = 1.0 - 0.06 * exp(-(t - segStart) / 0.012)
            var s = 0.0
            for (k in 0..3) s += oscs[k].saw(f0 * ratios[k] * bend, sr) * amps[k]
            s = tanh(2.2 * s)
            s = hp.hp(s)
            s = s * 0.6 + bp.processL(s) * 0.9
            x[i] = lp.lp(s) * g
        }
        return withReverb("Air Horn", x, sr, 0.18, 0.6f, 0.6)
    }

    fun siren(sr: Int): SampleSound {
        val n = len(sr, 3.2)
        val x = DoubleArray(n)
        val o1 = Osc()
        val o2 = Osc()
        val lp = OnePole(coef(4000.0, sr))
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val f = 700 + 550 * (0.5 - 0.5 * cos(2 * PI * t / 1.6))
            val s = o1.tri(f, sr) * 0.8 + o2.saw(f, sr) * 0.25
            val e = min(1.0, t / 0.05) * min(1.0, (3.2 - t) / 0.15)
            x[i] = lp.lp(s) * e
        }
        return mono("Siren", x, sr, 0.6f)
    }

    fun dubSiren(sr: Int): SampleSound {
        val n = len(sr, 3.4)
        val l = FloatArray(n)
        val r = FloatArray(n)
        val osc = Osc()
        var lfo = 0.0
        val lp = OnePole(coef(3500.0, sr))
        val dl = DelayLine(len(sr, 0.4))
        val dr = DelayLine(len(sr, 0.4))
        val d = sr * 0.33
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            lfo += 6.0 / sr
            if (lfo >= 1) lfo -= 1.0
            val f = 320.0 * (1.0 + 0.7 * (1.0 - lfo))
            val on = if (t < 1.6) min(1.0, t / 0.01) * min(1.0, (1.6 - t) / 0.02).coerceAtLeast(0.0) else 0.0
            val s = (lp.lp(osc.square(f, sr)) * on).toFloat() * 0.6f
            val el = dl.read(d)
            val er = dr.read(d * 1.5)
            dl.write(s + el * 0.55f)
            dr.write(s + er * 0.5f)
            l[i] = s + el * 0.7f
            r[i] = s + er * 0.7f
        }
        return finish("Dub Siren", l, r, sr)
    }

    fun laser(sr: Int): SampleSound {
        val n = len(sr, 0.85)
        val l = FloatArray(n)
        val r = FloatArray(n)
        val osc = Osc()
        val sq = Osc()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val k = (t / 0.25).toInt()
            val tz = t - k * 0.25
            if (k > 2 || tz > 0.2) continue
            val f = 2800 * exp(-tz * 14) + 150
            val s = (osc.sine(f, sr) + 0.3 * sq.square(f, sr)) * exp(-tz / 0.09)
            val pan = when (k) { 0 -> 0.2; 1 -> 0.8; else -> 0.5 }
            l[i] = (s * (1 - pan) * 1.4).toFloat()
            r[i] = (s * pan * 1.4).toFloat()
        }
        return finish("Laser", l, r, sr)
    }

    fun rewind(sr: Int): SampleSound {
        val src = beatLoop(sr, 4.0, 11)
        val n = len(sr, 1.35)
        val x = DoubleArray(n)
        var pos = 3.9
        val lp = OnePole(coef(6000.0, sr))
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val rate = 1.0 + 11.0 * (t / 1.2).pow(2.0)
            pos -= rate / sr
            val e = min(1.0, (1.35 - t) / 0.15)
            x[i] = lp.lp(readAt(src, sr, pos)) * e
        }
        return mono("Rewind", x, sr)
    }

    fun gunshot(sr: Int): SampleSound {
        val n = len(sr, 0.5)
        val x = DoubleArray(n)
        val noise = Noise(5)
        val lp = OnePole(coef(3000.0, sr))
        val osc = Osc()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val crack = if (t < 0.004) noise.next() else 0.0
            val body = lp.lp(noise.next()) * exp(-t / 0.06) * 1.6
            val thump = osc.sine(45 + 65 * exp(-t / 0.03), sr) * exp(-t / 0.12)
            x[i] = tanh(1.5 * (crack + body + thump))
        }
        return withReverb("Gunshot", x, sr, 0.4, 0.86f, 1.4)
    }

    fun bombDrop(sr: Int): SampleSound {
        val whistle = 1.8
        val n = len(sr, whistle + 1.6)
        val x = DoubleArray(n)
        val w = Osc()
        val sub = Osc()
        val noise = Noise(9)
        val lp = Biquad()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            var s = 0.0
            if (t < whistle) {
                val f = 2200 * 0.35.pow(t / whistle) * (1 + 0.01 * sin(2 * PI * 6 * t))
                s += w.sine(f, sr) * 0.4 * min(1.0, t / 0.2)
            } else {
                val te = t - whistle
                if (i % 32 == 0) lp.setLowPass(sr, (4000 * exp(-te / 0.5)).coerceAtLeast(250.0), 0.8)
                s += lp.processL(noise.next()) * exp(-te / 0.6) * 1.4
                s += sub.sine(30 + 25 * exp(-te / 0.3), sr) * exp(-te / 1.0) * 1.2
            }
            x[i] = tanh(s)
        }
        return withReverb("Bomb Drop", x, sr, 0.25, 0.85f, 1.0)
    }

    fun scratch(sr: Int): SampleSound {
        // Source: a short "ahh" vocal-like sound, then moved back and forth like a record.
        val srcSec = 0.6
        val src = DoubleArray(len(sr, srcSec))
        val o = Osc()
        val noise = Noise(3)
        val f1 = Biquad().apply { setBandPass(sr, 700.0, 4.0) }
        val f2 = Biquad().apply { setBandPass(sr, 1150.0, 5.0) }
        val f3 = Biquad().apply { setBandPass(sr, 2600.0, 6.0) }
        for (i in src.indices) {
            val t = i.toDouble() / sr
            val s = o.saw(140.0, sr) + noise.next() * 0.2
            src[i] = (f1.processL(s) * 1.0 + f2.processL(s) * 0.7 + f3.processL(s) * 0.35) * min(1.0, t / 0.02) * min(1.0, (srcSec - t) / 0.05)
        }
        val n = len(sr, 1.25)
        val x = DoubleArray(n)
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val pos = 0.05 + 0.2 * (0.5 - 0.5 * cos(2 * PI * 3.3 * t))
            x[i] = readAt(src, sr, pos)
        }
        return mono("Scratch", x, sr)
    }

    // =========================================================================================
    // Build-ups bank
    // =========================================================================================

    fun riser(sr: Int): SampleSound {
        val sec = 4.0
        val n = len(sr, sec)
        val l = FloatArray(n)
        val r = FloatArray(n)
        val noise = Noise(21)
        val bpL = Biquad()
        val bpR = Biquad()
        val o1 = Osc()
        val o2 = Osc()
        val lp = Biquad()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val k = t / sec
            if (i % 32 == 0) {
                val fc = 300 * (30.0).pow(k)
                bpL.setBandPass(sr, fc, 1.2)
                bpR.setBandPass(sr, fc * 1.05, 1.2)
                lp.setLowPass(sr, (400 * (25.0).pow(k)).coerceAtMost(sr * 0.45), 1.5)
            }
            val f = 180 * 2.0.pow(3 * k)
            val tone = lp.processL(o1.saw(f, sr) + o2.saw(f * 1.01, sr)) * 0.35
            val amp = k.pow(1.5)
            l[i] = ((bpL.processL(noise.next()) + tone) * amp).toFloat()
            r[i] = ((bpR.processL(noise.next()) + tone) * amp).toFloat()
        }
        return finish("Riser", l, r, sr)
    }

    fun downlifter(sr: Int): SampleSound {
        val sec = 3.0
        val n = len(sr, sec)
        val x = DoubleArray(n)
        val noise = Noise(22)
        val o = Osc()
        val lp = Biquad()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val k = t / sec
            if (i % 32 == 0) lp.setLowPass(sr, (12000 * (0.02).pow(k)).coerceAtLeast(120.0), 1.4)
            val f = 1400 * 2.0.pow(-3 * k)
            val s = lp.processL(noise.next() * 0.8 + o.saw(f, sr) * 0.5)
            x[i] = s * (1 - k).pow(2.0) * min(1.0, t / 0.01)
        }
        return mono("Downlifter", x, sr)
    }

    private fun noiseSweep(sr: Int, name: String, up: Boolean, seed: Long): SampleSound {
        val sec = 2.5
        val n = len(sr, sec)
        val l = FloatArray(n)
        val r = FloatArray(n)
        val noise = Noise(seed)
        val bl = Biquad()
        val br = Biquad()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val k = if (up) t / sec else 1 - t / sec
            if (i % 32 == 0) {
                bl.setBandPass(sr, 300 * (27.0).pow(k), 2.0)
                br.setBandPass(sr, 320 * (27.0).pow(k), 2.0)
            }
            val amp = if (up) k else k * min(1.0, t / 0.02)
            l[i] = (bl.processL(noise.next()) * amp).toFloat()
            r[i] = (br.processL(noise.next()) * amp).toFloat()
        }
        return finish(name, l, r, sr)
    }

    fun noiseUp(sr: Int) = noiseSweep(sr, "Noise Up", true, 31)
    fun noiseDown(sr: Int) = noiseSweep(sr, "Noise Down", false, 32)

    fun impact(sr: Int): SampleSound {
        val n = len(sr, 1.6)
        val x = DoubleArray(n)
        val o = Osc()
        val noise = Noise(41)
        val lp = OnePole(coef(2500.0, sr))
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val boom = o.sine(32 + 43 * exp(-t / 0.25), sr) * exp(-t / 0.9)
            val hit = lp.lp(noise.next()) * exp(-t / 0.05) * 1.5
            x[i] = tanh(1.3 * (boom + hit))
        }
        return withReverb("Impact", x, sr, 0.3, 0.9f, 1.4)
    }

    fun subDrop(sr: Int): SampleSound {
        val sec = 2.2
        val n = len(sr, sec)
        val x = DoubleArray(n)
        val o = Osc()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val f = 95 * 0.33.pow(t / sec)
            x[i] = tanh(1.5 * o.sine(f, sr)) * env(t, 0.005, 1.2)
        }
        return mono("Sub Drop", x, sr)
    }

    private fun metal(sr: Int, sec: Double, decay: Double, hpHz: Double, seed: Long): DoubleArray {
        val n = len(sr, sec)
        val x = DoubleArray(n)
        val freqs = doubleArrayOf(205.3, 304.4, 369.6, 522.7, 540.0, 800.0)
        val oscs = Array(6) { Osc() }
        val hp = Biquad().apply { setHighPass(sr, hpHz, 0.8) }
        val noise = Noise(seed)
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            var s = 0.0
            for (k in 0..5) s += oscs[k].square(freqs[k] * 2.0, sr)
            s = s / 6 + noise.next() * 0.3
            x[i] = hp.processL(s) * exp(-t / decay)
        }
        return x
    }

    fun reverseCymbal(sr: Int): SampleSound {
        val x = metal(sr, 2.2, 0.7, 5000.0, 51)
        x.reverse()
        return mono("Reverse Cymbal", x, sr)
    }

    fun vinylStop(sr: Int): SampleSound {
        val src = beatLoop(sr, 2.0, 61)
        val n = len(sr, 1.5)
        val x = DoubleArray(n)
        var pos = 0.0
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val rate = max(0.0, 1.0 - t / 1.3)
            pos += rate / sr
            x[i] = readAt(src, sr, pos) * min(1.0, (1.5 - t) / 0.2)
        }
        return mono("Vinyl Stop", x, sr)
    }

    // =========================================================================================
    // Drums bank
    // =========================================================================================

    fun kick(sr: Int): SampleSound {
        val n = len(sr, 0.6)
        val x = DoubleArray(n)
        val o = Osc()
        val noise = Noise(71)
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val f = 48 + 110 * exp(-t / 0.035)
            x[i] = tanh(1.3 * (o.sine(f, sr) * exp(-t / 0.28) + noise.next() * exp(-t / 0.003) * 0.3))
        }
        return mono("Kick", x, sr)
    }

    fun snare(sr: Int): SampleSound {
        val n = len(sr, 0.35)
        val x = DoubleArray(n)
        val o1 = Osc()
        val o2 = Osc()
        val noise = Noise(72)
        val hp = OnePole(coef(1200.0, sr))
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val tone = (o1.sine(185.0, sr) + 0.5 * o2.sine(330.0, sr)) * exp(-t / 0.06)
            x[i] = tone * 0.5 + hp.hp(noise.next()) * exp(-t / 0.14) * 0.8
        }
        return mono("Snare", x, sr)
    }

    fun clap(sr: Int): SampleSound {
        val n = len(sr, 0.4)
        val x = DoubleArray(n)
        val noise = Noise(73)
        val bp = Biquad().apply { setBandPass(sr, 1200.0, 1.5) }
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            var e = 0.0
            for (s in doubleArrayOf(0.0, 0.011, 0.022)) if (t >= s) e = max(e, exp(-(t - s) / 0.006))
            if (t >= 0.033) e = max(e, exp(-(t - 0.033) / 0.12))
            x[i] = bp.processL(noise.next()) * e
        }
        return mono("Clap", x, sr)
    }

    fun hat(sr: Int, open: Boolean): SampleSound {
        val x = metal(sr, if (open) 0.6 else 0.12, if (open) 0.25 else 0.04, 7000.0, if (open) 75L else 74L)
        return mono(if (open) "Open Hat" else "Hi-Hat", x, sr)
    }

    fun rim(sr: Int): SampleSound {
        val n = len(sr, 0.1)
        val x = DoubleArray(n)
        val o = Osc()
        val noise = Noise(76)
        val bp = Biquad().apply { setBandPass(sr, 2500.0, 2.0) }
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            x[i] = o.sine(1700.0, sr) * exp(-t / 0.012) + bp.processL(noise.next()) * exp(-t / 0.008)
        }
        return mono("Rim", x, sr)
    }

    fun tom(sr: Int): SampleSound {
        val n = len(sr, 0.5)
        val x = DoubleArray(n)
        val o = Osc()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            x[i] = o.sine(110 + 60 * exp(-t / 0.05), sr) * exp(-t / 0.2)
        }
        return mono("Tom", x, sr)
    }

    fun bass808(sr: Int): SampleSound {
        val n = len(sr, 1.6)
        val x = DoubleArray(n)
        val o = Osc()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            x[i] = tanh(1.8 * o.sine(52 + 25 * exp(-t / 0.04), sr)) * env(t, 0.002, 0.8)
        }
        return mono("808", x, sr)
    }

    // =========================================================================================
    // Hype bank
    // =========================================================================================

    fun whistle(sr: Int): SampleSound {
        val n = len(sr, 1.2)
        val x = DoubleArray(n)
        val o = Osc()
        val o2 = Osc()
        val noise = Noise(81)
        val bp = Biquad().apply { setBandPass(sr, 3000.0, 2.0) }
        val segs = listOf(0.0 to 0.2, 0.28 to 0.48, 0.56 to 1.1)
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val f = 2900 + 200 * sin(2 * PI * 28 * t)
            val s = o.sine(f, sr) + 0.2 * o2.sine(2 * f, sr) + bp.processL(noise.next()) * 0.4
            x[i] = s * gate(t, segs, 0.005, 0.02)
        }
        return mono("Whistle", x, sr, 0.6f)
    }

    fun cowbell(sr: Int): SampleSound {
        val n = len(sr, 0.5)
        val x = DoubleArray(n)
        val a = Osc()
        val b = Osc()
        val bp = Biquad().apply { setBandPass(sr, 900.0, 1.0) }
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val s = a.square(587.0, sr) + b.square(845.0, sr)
            x[i] = bp.processL(s) * (0.6 * exp(-t / 0.06) + 0.4 * exp(-t / 0.25))
        }
        return mono("Cowbell", x, sr)
    }

    fun zap(sr: Int): SampleSound {
        val n = len(sr, 0.45)
        val x = DoubleArray(n)
        val o = Osc()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val k = (t / 0.2).toInt()
            val tz = t - k * 0.2
            if (k > 1 || tz > 0.15) continue
            val f = 150 * 20.0.pow(min(1.0, tz / 0.12))
            x[i] = o.square(f, sr) * 0.5 * exp(-tz / 0.08)
        }
        return mono("Zap", x, sr, 0.6f)
    }

    fun drumRoll(sr: Int): SampleSound {
        val sec = 2.2
        val n = len(sr, sec)
        val x = DoubleArray(n)
        val noise = Noise(83)
        val hp = OnePole(coef(1000.0, sr))
        val o = Osc()
        val hits = ArrayList<Double>()
        var t = 0.0
        while (t < sec - 0.2) {
            hits += t
            val k = t / sec
            t += 0.12 - 0.09 * k
        }
        val hitIdx = hits.map { (it * sr).toInt() }
        var next = 0
        var last = -1.0
        for (i in 0 until n) {
            val tt = i.toDouble() / sr
            if (next < hitIdx.size && i >= hitIdx[next]) { last = tt; next++ }
            if (last < 0) continue
            val dt = tt - last
            val vel = 0.3 + 0.7 * (tt / sec)
            x[i] = (hp.hp(noise.next()) * 0.8 + o.sine(190.0, sr) * 0.4) * exp(-dt / 0.07) * vel
        }
        return mono("Drum Roll", x, sr)
    }

    fun bell(sr: Int): SampleSound {
        val n = len(sr, 2.5)
        val x = DoubleArray(n)
        val fc = 880.0
        val fm = fc * 1.4
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val index = 4 * exp(-t / 0.4)
            val s = sin(2 * PI * fc * t + index * sin(2 * PI * fm * t)) + 0.3 * sin(2 * PI * fc * 2.76 * t) * exp(-t / 0.5)
            x[i] = s * env(t, 0.002, 0.9)
        }
        return mono("Bell", x, sr)
    }

    fun alarm(sr: Int): SampleSound {
        val n = len(sr, 2.0)
        val x = DoubleArray(n)
        val o = Osc()
        val lp = OnePole(coef(3000.0, sr))
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val k = (t / 0.25).toInt()
            val f = if (k % 2 == 0) 960.0 else 770.0
            x[i] = lp.lp(o.square(f, sr)) * 0.6
        }
        return mono("Alarm", x, sr, 0.45f)
    }

    fun woosh(sr: Int): SampleSound {
        val sec = 1.5
        val n = len(sr, sec)
        val l = FloatArray(n)
        val r = FloatArray(n)
        val noise = Noise(85)
        val bp = Biquad()
        for (i in 0 until n) {
            val t = i.toDouble() / sr
            val k = t / sec
            if (i % 32 == 0) bp.setBandPass(sr, 400 + 4600 * sin(PI * k), 1.5)
            val s = bp.processL(noise.next()) * sin(PI * k).pow(2.0)
            l[i] = (s * (1 - k)).toFloat()
            r[i] = (s * k).toFloat()
        }
        return finish("Woosh", l, r, sr)
    }

    fun glitch(sr: Int): SampleSound {
        val src = beatLoop(sr, 1.3, 87)
        val n = len(sr, 1.2)
        val x = DoubleArray(n)
        val rnd = Random(88)
        val seg = len(sr, 0.06)
        var i = 0
        while (i < n) {
            val mode = rnd.nextInt(4)
            val grain = len(sr, 0.015)
            val start = rnd.nextInt(max(1, src.size - seg))
            for (j in 0 until seg) {
                if (i + j >= n) break
                val v = when (mode) {
                    0 -> src[start + j % grain]
                    1 -> src[start + (seg - 1 - j)]
                    2 -> floor(src[start + j] * 6) / 6
                    else -> src[start + j / 2 * 2]
                }
                x[i + j] = v
            }
            i += seg
        }
        return mono("Glitch", x, sr)
    }
}
